theorem.raw:
\thlabel{splitrec}
Let $H \leq E$ be a subgroup of a group $E$. Then:
\begin{enumerate}
\item There exists a map $p : E \to H$ such that $p (1) = 1$ and
for any $h\in H$, $x\in E$
\begin{equation}\eqlabel{33ab}
p ( h \, x ) = h \, p (x)
\end{equation}
\item For such a map $p : E \to H$ we define $S = S_p := p^{-1}(1)
= \{ x\in E \, |\, p (x) = 1 \}$. Then the multiplication map
\begin{equation}\eqlabel{335b}
\varphi : H \times S \to E, \quad \varphi ( h, s) := h s
\end{equation}
for all $h\in H$ and $s\in S$ is bijective with the inverse given
for any $x\in E$ by
$$
\varphi^{-1} : E \to H \times S, \quad \varphi^{-1} (x) = \bigl(
p(x), \, p (x)^{-1} \, x \bigl)
$$
\item For $p$ and $S$ as above there exist four maps $ \triangleright =
\triangleright_p: S\times H \to H$, $\triangleleft = \triangleleft_p : S\times H \to S$, $f =
f_p : S\times S \to H$ and $\ast = \ast_p : S\times S \to S$ given
by the formulas
\begin{eqnarray*}
s \triangleright h &{:=}& p (sh), \,\,\,\,\,\,\,\,\,\,\,  s\triangleleft h := p(sh)^{-1} s h \eqlabel{acti12}\\
f(s_1, s_2) &{:=}& p (s_1 s_2), \,\,\,\, s_1 \ast s_2 := p(s_1
s_2)^{-1} s_1 s_2
\end{eqnarray*}
for all $s$, $s_1$, $s_2 \in S$ and $h\in H$. Using these maps,
the unique group structure $'\cdot'$ on the set $H \times S$ such
that $\varphi : (H \times S, \cdot) \to E$ is an isomorphism of
groups is given by:
\begin{equation}\eqlabel{inmultireau}
(h_{1}, s_{1}) \cdot (h_{2}, s_{2}) := \Bigl( \, h_{1} (s_{1}
\triangleright h_{2}) f(s_{1} \triangleleft h_{2}, s_{2}), \,\,
(s_{1} \triangleleft h_{2}) \ast s_{2} \Bigl )
\end{equation}
for all $h_1$, $h_2 \in H$ and $s_1$, $s_2\in S$.
\end{enumerate}

\thlabel{constr}
Let $H$ be a group and $\Omega(H) = \bigl( (S, 1_S, \ast),
\triangleleft, \, \triangleright, \, f \bigl)$ an extending datum
of $H$. The following statements are equivalent:

$(1)$ $A \ltimes H$ is an unified product;

$(2)$ The following compatibilities hold for any $s$, $s_1$,
$s_2$, $s_3 \in S$ and $h$, $h_1$, $h_2 \in H$:

\begin{enumerate}
\item[(ES1)] The map $\triangleleft : S\times H \to S$ is a right action of
the group $H$ on the set $S$;

\item[(ES2)]  $(s_{1} \ast s_{2}) \ast s_{3} = \bigl( s_{1}
\triangleleft f(s_{2},s_{3}) \bigl ) \ast (s_{2} \ast s_{3});$

\item[(ES3)] $s \triangleright(h_{1} h_{2}) = (s \triangleright
h_{1}) \bigl( (s \triangleleft h_{1}) \triangleright h_{2}
\bigl);$

\item[(ES4)] $(s_{1} \ast s_{2}) \triangleleft h = \bigl ( s_{1}
\triangleleft (s_{2} \triangleright h) \bigl ) \ast (s_{2}
\triangleleft h);$

\item[(ES5)] $\bigl( s_{1} \triangleright(s_{2}\triangleright
h)\bigl) f \bigl( s_{1} \triangleleft (s_{2}\triangleright h), \,
s_{2} \triangleleft h \bigl ) =  f(s_{1}, \, s_{2}) \bigl( (s_{1}
\ast s_{2} ) \triangleright h \bigl);$

\item[(ES6)] $f(s_{1}, \, s_{2}) f(s_{1} \ast s_{2}, \, s_{3}) =
\bigl (s_{1} \triangleright f(s_{2}, \, s_{3})\bigl ) f\bigl
(s_{1} \triangleleft f(s_{2}, s_{3}), \, s_{2} \ast s_{3}\bigl );$

\item[(ES7)] For any $s\in S$ there exists $s'\in S$ such that $s'
\ast s = 1_S$.
\end{enumerate}

\thlabel{univers}
Let $H$ be a group and $\Omega (H) = \bigl( (S, 1_S, \ast),
\triangleleft, \, \triangleright, \, f \bigl)$ a group extending
structure of $H$. Then:

\begin{enumerate}
\item[(1)] $(H \ltimes_{\Omega} S, (i_H, i_S))$ is an initial
object of ${}_{\Omega (H)}{\mathcal C}$, where $i_H : H\rightarrow
H \ltimes_{\Omega} S$ and $i_S:S\rightarrow H \ltimes_{\Omega} S$
are the canonical inclusions;

\item[(2)] $(H \ltimes_{\Omega} S, (\pi_H, \pi_S))$ is a final
object of ${\mathcal D}_{\Omega (H)}$, where $\pi_H : H
\ltimes_{\Omega} S\rightarrow H $ and $\pi_S :H \ltimes_{\Omega}
S\rightarrow S$ are the canonical projections.
\end{enumerate}

proposition.raw:
\prlabel{clasif2}
Let $\Omega (H) = \bigl( (S, 1_S, \ast), \triangleleft, \,
\triangleright, \, f \bigl)$, $\Omega ' (H) = \bigl( (S, 1_{S},
\ast'), \triangleleft', \, \triangleright', \, f' \bigl)$ be two
group extending structures of a group $H$. Then there exists a
morphism $\psi : H \ltimes_{\Omega} S \to H \ltimes_{\Omega'} S$
that stabilizes $H$ and $S$ if and only if $\triangleleft = \triangleleft'$ and there
exists a unitary map $r: S \rightarrow H$ such that $\triangleright$, $\ast$
and $f$ are implemented by $\triangleright '$, $\ast'$ and $f'$ via $r$ as
follows:
\begin{eqnarray}
s \triangleright h &=& r(s)\, \bigl(s \triangleright'
h \bigl) \, r(s \triangleleft h)^{-1} \eqlabel{p2b} \\
s_{1} \ast s_{2} &=& \bigl( s_{1} \triangleleft r(s_{2})\bigl) \,
\ast' \, s_{2} \eqlabel{p3b}\\
f(s_1, s_2) &=& r(s_{1}) \, \bigl( s_{1} \triangleright' r(s_{2}) \bigl) \,
f' ( s_{1} \triangleleft r(s_{2}), \, s_2 ) \, r(s_{1} * s_{2})^{-1}
\eqlabel{p4b}
\end{eqnarray}
for all $s$, $s_{1}$, $s_{2} \in S$ and $h \in H$. Furthermore,
any morphism of groups $\psi : H \ltimes S \to H \ltimes' S$ that
stabilizes $H$ and $S$ is an isomorphism of groups and is given by
\begin{equation}\eqlabel{p5b}
\psi(h, \, s) = \bigl(h \, r(s), \, s\bigl)
\end{equation}
for all $h \in H$, $s \in S$.

remark.raw:
\relabel{recon}
Schreier's theorem states that any extension $E$ of $H$ by a
group $G$ is equivalent to a crossed product extension. We recall
in detail this construction for further use. Let $H\unlhd E$ be a
normal subgroup of a group $E$ and $G := E/H$ the quotient group.
Let $\pi : E \to G$ be the canonical projection and $\chi : G \to
E$ be a section as a map of $\pi$ with $\chi (1_G) = 1_E$. Using
$\chi$ we define a weak action $\alpha$ and a cocycle $f$ by the
formulas:
\begin{equation}\eqlabel{1act}
\alpha : G \rightarrow {\rm Aut}\, (H), \qquad \, \alpha (g) (h) = g \triangleright
h : = \chi (g) h \chi (g)^{-1}
\end{equation}
\begin{equation}\eqlabel{1coc}
f : G \times G \rightarrow H, \qquad f (g_1, g_2) := \chi (g_1)
\chi (g_2) \chi (g_1 g_2)^{-1}
\end{equation}
for all $g\in G$, $g_1$, $g_2 \in G$ and $h\in H$. Then $(H, G,
\alpha, f)$ is a normalized crossed system of groups and
$$
\theta : H \#_{\alpha}^{f} \, G \to E, \qquad \theta (h, g) := h
\chi (g)
$$
is an isomorphism of groups. For more details we refer the reader
to \cite[Theorem 2.6]{am1}.

